// SwiftUI output: one generated file with the mark geometry, the motion tracks and `BrandMarkView`.
// Works on iOS, tvOS, watchOS and macOS (SwiftUI Canvas + TimelineView, no dependency).
import { LOGO_MOTION } from '../../src/motion.mjs';
import { IDS, geometry } from '../../src/marks.mjs';
import { n, nameOf } from './draw.mjs';
import { swiftTrack } from './motion.mjs';
import * as P from './path.mjs';

/** Flat number list of a path: 0 x y = move, 1 x y = line, 2 x1 y1 x2 y2 x y = curve, 3 = close. */
function flat(d) {
  const out = [];
  for (const s of P.parse(d)) {
    if (s.c === 'M') out.push(0, s.x, s.y);
    else if (s.c === 'L') out.push(1, s.x, s.y);
    else if (s.c === 'C') out.push(2, s.x1, s.y1, s.x2, s.y2, s.x, s.y);
    else out.push(3);
  }
  return `[${out.map((v) => n(v)).join(', ')}]`;
}

function geometryLiteral(geo) {
  const lines = geo.lines.map((l) => `BrandLine(${l.role === 'b' ? 'true' : 'false'}, ${flat(l.d)})`).join(',\n            ');
  const [cx, cy, r] = geo.dot;
  return `BrandGeometry(grid: ${geo.grid}, stroke: ${geo.w}, dotX: ${cx}, dotY: ${cy}, dotR: ${r}, lines: [\n            ${lines},\n        ])`;
}

export function swiftBrand() {
  const M = LOGO_MOTION;
  const cases = IDS.map((id) => `    case ${id}`).join('\n');
  const names = IDS.map((id) => `        case .${id}: "${nameOf(id)}"`).join('\n');
  const master = IDS.map((id) => `        case .${id}: ${geometryLiteral(geometry(id).master)}`).join('\n');
  const micro = IDS.map((id) => `        case .${id}: ${geometryLiteral(geometry(id).micro)}`).join('\n');
  const colorA = IDS.map((id) => `        case .${id}: dark ? Tokens.Product.${id === 'mark' ? 'tv' : id} : Tokens.ProductLight.${id === 'mark' ? 'tv' : id}`).join('\n');
  const colorB = IDS.map((id) => `        case .${id}: dark ? Tokens.Product.${id === 'mark' ? 'music' : id} : Tokens.ProductLight.${id === 'mark' ? 'music' : id}`).join('\n');
  const track = (t) => (t ? swiftTrack(t) : '[]');
  const anim = (name) => {
    const a = M[name];
    return `        case .${name}: BrandTracks(duration: ${n(a.duration / 1000)}, loops: ${a.loop ? 'true' : 'false'}, lineSpread: ${n(a.lineSpread ?? 0)}, trimStart: ${track(a.trimStart)}, lineOpacity: ${track(a.lineOpacity)}, dotScale: ${track(a.dotScale)}, shakeX: ${track(a.shakeX)})`;
  };
  return `// GENERATED by brand/scripts/build.mjs from brand/src/marks.mjs and brand/src/motion.mjs. Do not edit.
import SwiftUI

/// The MixAI family mark (\`mark\`) and the eight product glyphs.
public enum BrandProduct: String, CaseIterable, Sendable {
${cases}

    /// Name read by assistive technology.
    public var name: String {
        switch self {
${names}
        }
    }
}

/// One stroked line of a mark. \`path\` is a flat list: 0 x y = move, 1 x y = line, 2 x1 y1 x2 y2 x y = curve, 3 = close.
public struct BrandLine: Sendable {
    public let secondStream: Bool
    public let path: [Double]
    init(_ secondStream: Bool, _ path: [Double]) {
        self.secondStream = secondStream
        self.path = path
    }
}

/// Geometry of a mark on its grid: stroked lines (the sources) and one filled dot (the signal).
public struct BrandGeometry: Sendable {
    public let grid: Double
    public let stroke: Double
    public let dotX: Double
    public let dotY: Double
    public let dotR: Double
    public let lines: [BrandLine]
}

/// One keyframe: time 0...1, value, cubic-bezier easing into this key.
public struct BrandKey: Sendable {
    public let t: Double
    public let v: Double
    public let x1: Double
    public let y1: Double
    public let x2: Double
    public let y2: Double
    init(_ t: Double, _ v: Double, _ x1: Double, _ y1: Double, _ x2: Double, _ y2: Double) {
        self.t = t
        self.v = v
        self.x1 = x1
        self.y1 = y1
        self.x2 = x2
        self.y2 = y2
    }
}

/// Keyframe tracks of one logo animation. An empty track means "not animated".
public struct BrandTracks: Sendable {
    public let duration: Double
    public let loops: Bool
    /// The last line starts this share of the duration late; lines in between are spaced evenly.
    public let lineSpread: Double
    public let trimStart: [BrandKey]
    public let lineOpacity: [BrandKey]
    public let dotScale: [BrandKey]
    public let shakeX: [BrandKey]
}

/// Logo animations. Each one starts and ends on the static mark.
public enum BrandAnimation: Sendable {
    case intro
    case loading
    case success
    case error

    public var tracks: BrandTracks {
        switch self {
${['intro', 'loading', 'success', 'error'].map(anim).join('\n')}
        }
    }
}

public enum Brand {
    /// Press feedback of a tappable mark.
    public static let pressScale: Double = ${M.press.scale}
    public static let pressDuration: Double = ${n(M.press.duration / 1000)}
    /// Splash to first screen: total time of the morph.
    public static let morphDuration: Double = ${n(M.morph.duration / 1000)}

    /// Geometry for sizes above 16 pt.
    public static func geometry(_ product: BrandProduct) -> BrandGeometry {
        switch product {
${master}
        }
    }

    /// Geometry drawn for 16 pt and below.
    public static func microGeometry(_ product: BrandProduct) -> BrandGeometry {
        switch product {
${micro}
        }
    }

    static func streamA(_ product: BrandProduct, dark: Bool) -> Color {
        switch product {
${colorA}
        }
    }

    static func streamB(_ product: BrandProduct, dark: Bool) -> Color {
        switch product {
${colorB}
        }
    }

    /// Value of a track at \`time\` (0...1). An empty track returns \`rest\`.
    public static func value(_ keys: [BrandKey], at time: Double, rest: Double) -> Double {
        guard let first = keys.first, let last = keys.last else { return rest }
        if time <= first.t { return first.v }
        if time >= last.t { return last.v }
        for i in 1..<keys.count where time <= keys[i].t {
            let a = keys[i - 1]
            let b = keys[i]
            let local = (time - a.t) / (b.t - a.t)
            return a.v + (b.v - a.v) * ease(local, b.x1, b.y1, b.x2, b.y2)
        }
        return last.v
    }

    /// cubic-bezier(x1, y1, x2, y2) evaluated at \`x\`.
    static func ease(_ x: Double, _ x1: Double, _ y1: Double, _ x2: Double, _ y2: Double) -> Double {
        if x1 == y1 && x2 == y2 { return x }
        func curve(_ t: Double, _ p1: Double, _ p2: Double) -> Double {
            let u = 1 - t
            return 3 * u * u * t * p1 + 3 * u * t * t * p2 + t * t * t
        }
        var lo = 0.0
        var hi = 1.0
        var t = x
        for _ in 0..<24 {
            let at = curve(t, x1, x2)
            if abs(at - x) < 0.0005 { break }
            if at < x { lo = t } else { hi = t }
            t = (lo + hi) / 2
        }
        return curve(t, y1, y2)
    }

    static func path(_ flat: [Double]) -> Path {
        var p = Path()
        var i = 0
        while i < flat.count {
            switch flat[i] {
            case 0:
                p.move(to: CGPoint(x: flat[i + 1], y: flat[i + 2]))
                i += 3
            case 1:
                p.addLine(to: CGPoint(x: flat[i + 1], y: flat[i + 2]))
                i += 3
            case 2:
                p.addCurve(
                    to: CGPoint(x: flat[i + 5], y: flat[i + 6]),
                    control1: CGPoint(x: flat[i + 1], y: flat[i + 2]),
                    control2: CGPoint(x: flat[i + 3], y: flat[i + 4]))
                i += 7
            default:
                p.closeSubpath()
                i += 1
            }
        }
        return p
    }
}

/// The MixAI mark or a product glyph, drawn as vectors. Square; give it a frame.
///
/// \`animation\` plays from the moment the view appears. With Reduce Motion on, or with \`animation == nil\`,
/// the view shows the static mark (a loading state must then show a text status next to it).
public struct BrandMarkView: View {
    private let product: BrandProduct
    private let animation: BrandAnimation?
    private let tint: Color?
    private let decorative: Bool

    @Environment(\\.accessibilityReduceMotion) private var reduceMotion
    @Environment(\\.colorScheme) private var colorScheme
    @State private var started = Date()

    /// - Parameters:
    ///   - tint: one colour for the whole mark (lines and dot); nil = brand colours.
    ///   - decorative: hide from assistive technology (use when the name is next to it).
    public init(_ product: BrandProduct = .mark, animation: BrandAnimation? = nil, tint: Color? = nil, decorative: Bool = false) {
        self.product = product
        self.animation = animation
        self.tint = tint
        self.decorative = decorative
    }

    public var body: some View {
        Group {
            if let animation, !reduceMotion {
                TimelineView(.animation) { context in
                    canvas(tracks: animation.tracks, elapsed: context.date.timeIntervalSince(started))
                }
            } else {
                canvas(tracks: nil, elapsed: 0)
            }
        }
        .aspectRatio(1, contentMode: .fit)
        .accessibilityHidden(decorative)
        .accessibilityLabel(Text(verbatim: product.name))
        .onAppear { started = Date() }
    }

    private func canvas(tracks: BrandTracks?, elapsed: Double) -> some View {
        let dark = colorScheme == .dark
        let a = tint ?? Brand.streamA(product, dark: dark)
        let b = tint ?? Brand.streamB(product, dark: dark)
        let signal = tint ?? (dark ? Tokens.Dark.foreground : Tokens.Light.foreground)
        return Canvas { context, size in
            let side = min(size.width, size.height)
            let geo = side <= 16 ? Brand.microGeometry(product) : Brand.geometry(product)
            let unit = side / geo.grid
            var shake = 0.0
            if let tracks { shake = Brand.value(tracks.shakeX, at: progress(tracks, elapsed, 0), rest: 0) * geo.grid / 48 }
            var ctx = context
            ctx.translateBy(x: (size.width - side) / 2 + shake * unit, y: (size.height - side) / 2)
            ctx.scaleBy(x: unit, y: unit)
            let style = StrokeStyle(lineWidth: geo.stroke, lineCap: .round, lineJoin: .round)
            for (index, line) in geo.lines.enumerated() {
                var trim = 0.0
                var opacity = 1.0
                if let tracks {
                    let position = geo.lines.count > 1 ? Double(index) / Double(geo.lines.count - 1) : 0
                    let t = progress(tracks, elapsed, position * tracks.lineSpread)
                    trim = Brand.value(tracks.trimStart, at: t, rest: 0)
                    opacity = Brand.value(tracks.lineOpacity, at: t, rest: 1)
                }
                if trim >= 0.999 { continue }
                let path = Brand.path(line.path).trimmedPath(from: trim, to: 1)
                ctx.stroke(path, with: .color((line.secondStream ? b : a).opacity(opacity)), style: style)
            }
            var scale = 1.0
            if let tracks { scale = Brand.value(tracks.dotScale, at: progress(tracks, elapsed, 0), rest: 1) }
            let r = geo.dotR * scale
            ctx.fill(Path(ellipseIn: CGRect(x: geo.dotX - r, y: geo.dotY - r, width: r * 2, height: r * 2)), with: .color(signal))
        }
    }

    /// Progress 0...1 of a track that starts \`delay\` (share of the duration) late; loops wrap, others hold the end.
    private func progress(_ tracks: BrandTracks, _ elapsed: Double, _ delay: Double) -> Double {
        let raw = elapsed / tracks.duration - delay
        if tracks.loops { return raw < 0 ? 0 : raw.truncatingRemainder(dividingBy: 1) }
        return min(max(raw, 0), 1)
    }
}
`;
}
